<?php

declare(strict_types=1);

namespace App\Ordering\Application\Command\PlaceOrder;

use App\Shared\Domain\Currency;

/**
 * `orderId` is generated by the controller before the call, so an idempotent replay returns the same id.
 * Formats are checked at the HTTP boundary; ids are validated again when the identifier value objects are built.
 */
final readonly class PlaceOrderCommand
{
    public function __construct(
        public string $orderId,
        public string $customerId,
        public string $productId,
        public int $expectedAmount,
        public Currency $expectedCurrency,
    ) {}
}
